Dragging those sliders without a map is a good way to watch things change without learning much, so here is the map. Every point in it is a whole game, solved, and coloured by which equilibrium comes out. The dot is where your sliders currently sit.

```{ojs}
//| echo: false
classify = function(kk, sv, kv) {
  const p = (s, h) => {
    const a1 = kk === "reach" ? a1b + sv*s : a1b + sv*s - sv*h;
    const a2 = kk === "reach" ? a2b + sv*h : a2b + sv*h - sv*s;
    const r = eqp(a1, a2);
    return [r[0] - kv*s, r[1] - kv*h];
  };
  const sc = {0: p(1,0)[0] > p(0,0)[0] ? 1 : 0, 1: p(1,1)[0] > p(0,1)[0] ? 1 : 0};
  const hy = {0: p(0,1)[1] > p(0,0)[1] ? 1 : 0, 1: p(1,1)[1] > p(1,0)[1] ? 1 : 0};
  const ns = [];
  for (const s of [0,1]) for (const h of [0,1]) if (sc[h] === s && hy[s] === h) ns.push([s,h]);
  if (ns.length !== 1) return "more than one";
  const [s, h] = ns[0];
  if (s === 0 && h === 0) return "neither advertises";
  if (s === 1 && h === 0) return "Smart Cookie alone";
  if (s === 0 && h === 1) return "Hogi Yogi alone";
  const b = p(0,0);
  return (p(1,1)[0] < b[0] && p(1,1)[1] < b[1]) ? "both — and both lose" : "both advertise";
}

// depends on the campaign type only, so it is computed once per toggle
// rather than on every slider tick
mapCells = {
  const nx = 46, ny = 38, x0 = 0.25, x1 = 2.0, y0 = 0, y1 = 1.20;
  const dx = (x1-x0)/nx, dy = (y1-y0)/ny, out = [];
  for (let i = 0; i < nx; i++) for (let j = 0; j < ny; j++) {
    const x = x0 + i*dx, y = y0 + j*dy;
    out.push({x, y, dx, dy, r: classify(kind, x + dx/2, y + dy/2)});
  }
  return out;
}
```

